import React from 'react';
import { createRoot, hydrateRoot } from 'react-dom/client';
import { BrowserRouter } from 'react-router-dom';
import App from './App';
import { ThemeProvider } from '#providers/Theme';
// NOTE: theme.css is generated by `npm run build:theme` from src/tokens (D-002). Never hand-edit it.
import './styles/fonts.css';
import './styles/theme.css';
import './styles/tone.css';
import './styles/main.css';

const container = document.getElementById('root');
if (container) {
  const app = (
    <React.StrictMode>
      <ThemeProvider>
        <BrowserRouter>
          <App />
        </BrowserRouter>
      </ThemeProvider>
    </React.StrictMode>
  );
  // A built page arrives pre-rendered (scripts/prerender.ts) and React attaches to it. The dev server
  // sends an empty root, so React renders from scratch there (D-154).
  if (container.firstElementChild) hydrateRoot(container, app);
  else createRoot(container).render(app);
}
